extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var root := await instantiate_scene("res://node_2d.tscn")
	if not check("scena", root != null, "La scena res://node_2d.tscn deve aprirsi senza errori"):
		return
	var sprite1 := find_by_name(root, "Sprite2D") as Sprite2D
	if not check("sprite1", sprite1 != null, "La scena deve contenere il nodo Sprite2D"):
		return
	var sprite3 := find_by_name(root, "Sprite2D3") as Sprite2D
	if not check("sprite3", sprite3 != null, "La scena deve contenere il nodo Sprite2D3"):
		return
	var flipped = get_prop(sprite1, "flip_h", false)
	check("flip_orizzontale", flipped == true, "Il primo Sprite2D deve essere specchiato in orizzontale")
	var vis = get_prop(sprite3, "visible", true)
	check("sprite3_invisibile", vis == false, "Il nodo Sprite2D3 deve essere nascosto alla vista")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var root := await instantiate_scene("res://node_2d.tscn")
	if not check("scena", root != null, "La scena res://node_2d.tscn deve aprirsi senza errori"):
		return
	var sprite2 := find_by_name(root, "Sprite2D2") as Sprite2D
	if not check("sprite2", sprite2 != null, "La scena deve contenere il nodo Sprite2D2"):
		return
	var label := find_by_name(root, "Label") as Label
	if not check("label", label != null, "La scena deve contenere il nodo Label"):
		return
	var rot_deg = get_prop(sprite2, "rotation_degrees", 0.0)
	var rot_rad = get_prop(sprite2, "rotation", 0.0)
	var rot_ok: bool = abs(float(rot_deg) - 45.0) < 0.5 or is_equal_approx(float(rot_rad), deg_to_rad(45.0))
	check("rotazione_45", rot_ok, "Il nodo Sprite2D2 deve essere ruotato di 45 gradi")
	var is_upper = get_prop(label, "uppercase", false)
	check("testo_maiuscolo", is_upper == true, "Il nodo Label deve mostrare il testo a lettere maiuscole")
